rder:0;border-radius:20px;background:#cbd5e1;padding:2px;cursor:pointer}.switch:after{content:"";display:block;width:18px;height:18px;border-radius:50%;background:#fff;transition:.15s}.switch.on{background:#f54696}.switch.on:after{transform:translateX(17px)}.modal{position:fixed;inset:0;z-index:60;display:none;align-items:center;justify-content:center;padding:18px;background:rgba(5,18,40,.55)}.modal.show{display:flex}.modal-card{width:min(600px,100%);padding:24px;border-radius:15px;background:#fff}.form-grid{display:grid;grid-template-columns:1fr 1fr;gap:13px}.field.full{grid-column:1/-1}.field label{display:block;margin-bottom:5px;color:#53647d;font-size:11px;font-weight:800}.field input,.field select{width:100%;height:42px;padding:0 12px;border:1px solid #dce4ef;border-radius:9px;outline:none}.modal-actions{display:flex;justify-content:flex-end;gap:9px;margin-top:19px;padding-top:16px;border-top:1px solid #edf1f6}@media(max-width:1100px){.road-row{grid-template-columns:80px 1fr 100px 160px}.road-row>*:nth-child(3),.road-row>*:nth-child(5){display:none}.road-stats{grid-template-columns:repeat(2,1fr)}}@media(max-width:700px){.road-main{padding:16px}.road-hero{align-items:flex-start;flex-direction:column}.road-row{grid-template-columns:70px 1fr 110px}.road-row>*:nth-child(4){display:none}.road-toolbar{flex-direction:column}.form-grid{grid-template-columns:1fr}.field.full{grid-column:auto}}
