</main></div></div>
<div class="modal" id="task-modal"><form class="modal-card" id="task-form"><div class="flex items-center justify-between mb-5"><h2 id="modal-title" class="text-[18px] font-bold">เพิ่มภารกิจ</h2><button type="button" id="close-modal" class="text-[#718096]">✕</button></div><input type="hidden" id="task-id"><div class="form-grid"><div class="field full"><label>ชื่อภารกิจ *</label><input id="title" required maxlength="255"></div><div class="field"><label>ระดับ</label><select id="stage"><option value="tcas">ม.6 / TCAS</option><option value="m4">ม.4 - ม.5</option><option value="m1">ม.1 - ม.3</option></select></div><div class="field"><label>วิชา</label><input id="subject" value="ทั่วไป"></div><div class="field"><label>หมวดหมู่</label><input id="category" value="ทั่วไป"></div><div class="field"><label>วันครบกำหนด</label><input id="due-date" type="date"></div><div class="field"><label>แต้ม NC</label><input id="points" type="number" min="0" max="1000" value="10"></div><div class="field"><label>ลำดับ</label><input id="sort-order" type="number" min="0" value="0"></div><div class="field full"><label><input id="is-active" type="checkbox" checked style="width:auto;height:auto;margin-right:7px">เผยแพร่ให้นักเรียนเห็น</label></div></div><div class="modal-actions"><button class="road-btn" type="button" id="cancel-modal">ยกเลิก</button><button class="road-btn primary" type="submit">บันทึกภารกิจ</button></div></form></div>
<script>
let tasks=[]; const labels={tcas:'ม.6 / TCAS',m4:'ม.4 - ม.5',m1:'ม.1 - ม.3'};
const esc=value=>{const node=document.createElement('div');node.textContent=String(value??'');return node.innerHTML};
async function api(payload={},query=''){const response=await fetch('roadmap-api.php'+query,{method:query?'GET':'POST',headers:{'Content-Type':'application/json'},body:query?null:JSON.stringify(payload)});const data=await response.json();if(!response.ok||!data.success)throw new Error(data.message||'ดำเนินการไม่สำเร็จ');return data}
async function load(){const data=await api({},'?action=list');tasks=data.tasks;draw();document.getElementById('stat-all').textContent=tasks.length;document.getElementById('stat-active').textContent=tasks.filter(t=>Number(t.is_active)).length;document.getElementById('stat-tcas').textContent=tasks.filter(t=>t.stage==='tcas').length;document.getElementById('stat-progress').textContent=tasks.reduce((sum,t)=>sum+Number(t.student_records||0),0)}
function draw(){const q=document.getElementById('search').value.trim().toLowerCase(),stage=document.getElementById('stage-filter').value;const filtered=tasks.filter(t=>(!stage||t.stage===stage)&&(!q||(t.title+' '+t.subject+' '+t.category).toLowerCase().includes(q)));document.getElementById('task-list').innerHTML=filtered.length?filtered.map(t=>`<div class="road-row"><span class="stage">${labels[t.stage]}</span><div><div class="task-name">${esc(t.title)}</div><div class="task-sub">${esc(t.subject)} · ${esc(t.category)}</div></div><span>${t.due_date?new Date(t.due_date+'T00:00:00').toLocaleDateString('th-TH'):'—'}</span><strong>+${Number(t.points_reward)} NC</strong><button class="switch ${Number(t.is_active)?'on':''}" onclick="toggleTask(${t.id},${Number(t.is_active)?0:1})" aria-label="เปลี่ยนสถานะ"></button><div class="road-actions"><button onclick="editTask(${t.id})">แก้ไข</button><button class="danger" onclick="deleteTask(${t.id})">ลบ</button></div></div>`).join(''):'<div class="road-row"><span>ไม่พบภารกิจ</span></div>'}
function openModal(task=null){document.getElementById('task-form').reset();document.getElementById('task-id').value=task?.id||'';document.getElementById('modal-title').textContent=task?'แก้ไขภารกิจ':'เพิ่มภารกิจ';document.getElementById('title').value=task?.title||'';document.getElementById('stage').value=task?.stage||'tcas';document.getElementById('subject').value=task?.subject||'ทั่วไป';document.getElementById('category').value=task?.category||'ทั่วไป';document.getElementById('due-date').value=task?.due_date||'';document.getElementById('points').value=task?.points_reward??10;document.getElementById('sort-order').value=task?.sort_order??0;document.getElementById('is-active').checked=task?Number(task.is_active)===1:true;document.getElementById('task-modal').classList.add('show')}
const closeModal=()=>document.getElementById('task-modal').classList.remove('show');
function editTask(id){openModal(tasks.find(t=>Number(t.id)===Number(id)))}
async function toggleTask(id,is_active){await api({action:'toggle',id,is_active});await load()}
async function deleteTask(id){if(!confirm('ลบภารกิจนี้และความคืบหน้าที่เกี่ยวข้องหรือไม่?'))return;await api({action:'delete',id});await load()}
document.getElementById('task-form').addEventListener('submit',async event=>{event.preventDefault();await api({action:'save',id:Number(document.getElementById('task-id').value||0),title:document.getElementById('title').value,stage:document.getElementById('stage').value,subject:document.getElementById('subject').value,category:document.getElementById('category').value,due_date:document.getElementById('due-date').value,points_reward:Number(document.getElementById('points').value),sort_order:Number(document.getElementById('sort-order').value),is_active:document.getElementById('is-active').checked});closeModal();await load()});
document.getElementById('add-task').onclick=()=>openModal();document.getElementById('close-modal').onclick=closeModal;document.getElementById('cancel-modal').onclick=closeModal;document.getElementById('search').oninput=draw;document.getElementById('stage-filter').onchange=draw;load().catch(error=>{document.getElementById('task-list').innerHTML=`<div class="road-row"><span>${esc(error.message)}</span></div>`});
</script></body></html>
